  $skt$https://images.unsplash.com/photo-1615396899839-c99c121888b0?auto=format&fit=crop&w=1600&q=80$skt$,
  $skt$Orange skincare tubes arranged with halved citrus fruit$skt$,
  $skt$Nataliya Melnychuk$skt$,
  $skt$https://unsplash.com/@natinati?utm_source=SkinLabs&utm_medium=referral$skt$,
  '[]'::jsonb,
  $skt$Salicylic Acid for Blackheads: A Full Guide$skt$,
  $skt$Why salicylic acid targets blackheads specifically, typical concentrations, and how to build a routine around it without over-drying skin.$skt$,
  $skt${"@context": "https://schema.org", "@type": "Article", "headline": "Salicylic Acid for Blackheads: Why It Works Where Other Acids Don't", "description": "Why salicylic acid targets blackheads specifically, typical concentrations, and how to build a routine around it without over-drying skin.", "image": ["https://images.unsplash.com/photo-1615396899839-c99c121888b0?auto=format&fit=crop&w=1600&q=80"], "datePublished": "2026-08-25", "dateModified": "2026-08-25", "mainEntityOfPage": {"@type": "WebPage", "@id": "https://skinlabs.co.za/newsroom/salicylic-acid-bha-for-blackheads"}, "author": {"@type": "Organization", "name": "The Daily Skinny by SkinLabs"}, "publisher": {"@type": "Organization", "name": "SkinLabs", "logo": {"@type": "ImageObject", "url": "https://skinlabs.co.za/pwa-512.png"}}, "inLanguage": "en-ZA"}$skt$::jsonb,
