  $skt$Silhouette of a baobab tree backlit by the sun in Madagascar$skt$,
  $skt$Rafael Peier$skt$,
  $skt$https://unsplash.com/@rafaelpeier?utm_source=SkinLabs&utm_medium=referral$skt$,
  '[]'::jsonb,
  $skt$Best Sunscreen for Sweaty SA Summers | Sun Care Guide$skt$,
  $skt$How to pick a sunscreen that survives real South African summer heat, sweat and humidity, from Highveld to KZN coast.$skt$,
  $skt${"@context": "https://schema.org", "@type": "Article", "headline": "The Best Sunscreens For Sweaty South African Summers", "description": "How to pick a sunscreen that survives real South African summer heat, sweat and humidity, from Highveld to KZN coast.", "image": ["https://images.unsplash.com/photo-1781427012519-aafbf070094f?auto=format&fit=crop&w=1600&q=80"], "datePublished": "2026-08-01", "dateModified": "2026-08-01", "mainEntityOfPage": {"@type": "WebPage", "@id": "https://skinlabs.co.za/newsroom/best-sunscreens-for-sweaty-sa-summers"}, "author": {"@type": "Organization", "name": "The Daily Skinny by SkinLabs"}, "publisher": {"@type": "Organization", "name": "SkinLabs", "logo": {"@type": "ImageObject", "url": "https://skinlabs.co.za/pwa-512.png"}}, "inLanguage": "en-ZA"}$skt$::jsonb,
