  $skt${"@context": "https://schema.org", "@type": "Article", "headline": "Rooibos And Marula: South Africa's Best Skincare Botanicals", "description": "How South Africa's rooibos and marula work in skincare, and why they're genuinely useful, not just local-pride marketing.", "image": ["https://images.unsplash.com/photo-1623676714504-edd78728155e?auto=format&fit=crop&w=1600&q=80"], "datePublished": "2026-08-04", "dateModified": "2026-08-04", "mainEntityOfPage": {"@type": "WebPage", "@id": "https://skinlabs.co.za/newsroom/local-sa-botanical-ingredients-rooibos-marula"}, "author": {"@type": "Organization", "name": "The Daily Skinny by SkinLabs"}, "publisher": {"@type": "Organization", "name": "SkinLabs", "logo": {"@type": "ImageObject", "url": "https://skinlabs.co.za/pwa-512.png"}}, "inLanguage": "en-ZA"}$skt$::jsonb,
